    46	  return fromEpochSeconds(toEpochSeconds(t) + minutes * 60);
    47	}
    48	
    49	export function compare(a: LocalDateTime, b: LocalDateTime): number {
    50	  return toEpochSeconds(a) - toEpochSeconds(b);
    51	}
